module RDTest

using Test
using KernelSmoothing
using Distributions: Normal, ccdf

# reference values from rdrobust 4.1.1, generated by data/rdrobust_golden.R
include(joinpath(@__DIR__, "data", "rdrobust_golden.jl"))

# the data of the reference values: 600 observations of x in [-1, 1], with a jump of
# 0.4 at 0 in y, a fuzzy treatment with a jump in its probability, two covariates,
# 50 clusters and weights
const I = 1:600
const X = round.(2 .* mod.(I .* 0.6180339887498949, 1) .- 1, digits = 3)
const Z1 = cos.(2.3 .* I) .+ 0.5 .* X
const Z2 = sin.(1.1 .* I)
const Y = 0.5 .+ 0.8 .* X .- 0.3 .* X .^ 2 .+ 0.4 .* (X .>= 0) .+ 0.3 .* sin.(7.3 .* I)
const T = Float64.(ifelse.(X .>= 0, sin.(3.7 .* I) .> -0.6, sin.(3.7 .* I) .> 0.8))
const RESPONSES = Dict("y" => Y, "yc" => Y .+ 0.5 .* Z1 .- 0.3 .* Z2,
                       "yf" => 0.5 .+ 0.8 .* X .+ 0.6 .* T .+ 0.3 .* sin.(7.3 .* I))
const G = 1 .+ mod.(I, 50)
const W = 1.0 .+ mod.(I, 3)
const NPKERNELS = Dict("epa" => EpanechnikovKernel(), "tri" => TriangularKernel(), "uni" => UniformKernel())

rdvce(v) = v == "nn" ? NNVariance() : v[1:2] == "hc" ? HCVariance(parse(Int, v[3:end])) :
           ClusterVariance(parse(Int, v[3:end]))

@testset "agrees with rdrobust" begin
  for c in RDROBUST, compat in (true, false)
    m = fit(RegressionDiscontinuity, X, RESPONSES[c.y]; degree = c.p, derivative = c.deriv,
            kernel = NPKERNELS[c.kernel], vce = rdvce(c.vce), bandwidth = c.h, pilot = c.b,
            treatment = c.fuzzy ? T : nothing, covariates = c.covs ? hcat(Z1, Z2) : nothing,
            weights = c.weighted ? W : nothing, cluster = c.clustered ? G : nothing, compat)
    @test [m.nh...] == c.N_h && [m.nb...] == c.N_b
    @test [m.estimate, m.estimate_bc] ≈ c.coef[1:2] rtol = 1e-10
    @test [m.sides...] ≈ c.tau_lr rtol = 1e-10
    @test [m.bias...] ≈ c.bias rtol = 1e-8 atol = 1e-12
    # rdrobust has no factor (G - 1) / G for CR3, which ClusterVariance has by default
    f = c.vce == "cr3" && !compat ? sqrt(49 / 50) : 1.0
    @test m.se ≈ c.se[1] * f rtol = 1e-3 * (f != 1) + 1e-10
    @test m.se_rbc ≈ c.se[3] * f rtol = 1e-3 * (f != 1) + 1e-10
    if c.fuzzy
      @test [m.firststage.estimate, m.firststage.estimate_bc] ≈ c.tau_T[1:2] rtol = 1e-10
      @test [m.firststage.se, m.firststage.se_rbc] ≈ c.se_T[[1, 3]] rtol = 1e-10
    end
    c.covs && @test vec(m.gamma) ≈ c.gamma rtol = 1e-10
  end
end

@testset "the sides are local polynomial fits" begin
  # on each side, the fits are those of LocalPolynomialRegression at the cutoff with
  # the data of that side, for the variance estimators that agree
  for vce in (NNVariance(), HCVariance(0), HCVariance(1)), (p, ν) in ((1, 0), (2, 1))
    m = fit(RegressionDiscontinuity, X, Y; degree = p, derivative = ν, bandwidth = (0.35, 0.4), pilot = (0.5, 0.6), vce)
    l, r = X .< 0, X .>= 0
    fl = fit(LocalPolynomialRegression, X[l], Y[l]; degree = p, derivative = ν, bandwidth = 0.35, pilot = 0.5,
             points = [0.0], vce, minobs = 0, kernel = TriangularKernel())
    fr = fit(LocalPolynomialRegression, X[r], Y[r]; degree = p, derivative = ν, bandwidth = 0.4, pilot = 0.6,
             points = [0.0], vce, minobs = 0, kernel = TriangularKernel())
    @test m.estimate ≈ fr.estimate[1] - fl.estimate[1] rtol = 1e-12
    @test m.estimate_bc ≈ fr.estimate_bc[1] - fl.estimate_bc[1] rtol = 1e-12
    @test m.se ≈ hypot(fr.se[1], fl.se[1]) rtol = 1e-12
    @test m.se_rbc ≈ hypot(fr.se_rbc[1], fl.se_rbc[1]) rtol = 1e-12
  end
end

@testset "designs" begin
  ms = fit(RegressionDiscontinuity, X, Y; bandwidth = 0.3, pilot = 0.5, vce = HCVariance(1))
  # perfect compliance: the fuzzy design is the sharp one
  mf = fit(RegressionDiscontinuity, X, Y; treatment = Float64.(X .>= 0), bandwidth = 0.3, pilot = 0.5,
           vce = HCVariance(1))
  @test mf.firststage.estimate ≈ 1 rtol = 1e-12
  @test mf.estimate ≈ ms.estimate rtol = 1e-12
  @test mf.se ≈ ms.se rtol = 1e-10
  @test mf.se_rbc ≈ ms.se_rbc rtol = 1e-10
  # a cutoff elsewhere, with the data shifted, and responses rescaled
  m2 = fit(RegressionDiscontinuity, X .+ 5, 3 .* Y; cutoff = 5, bandwidth = 0.3, pilot = 0.5, vce = HCVariance(1))
  @test m2.estimate ≈ 3 * ms.estimate rtol = 1e-10
  @test m2.se_rbc ≈ 3 * ms.se_rbc rtol = 1e-10
  # a kink estimate scales with the units of x
  mk = fit(RegressionDiscontinuity, X, Y; derivative = 1, bandwidth = 0.5, pilot = 0.7)
  mk10 = fit(RegressionDiscontinuity, 10 .* X, Y; derivative = 1, bandwidth = 5, pilot = 7)
  @test mk10.estimate ≈ mk.estimate / 10 rtol = 1e-10
  @test mk10.se_rbc ≈ mk.se_rbc / 10 rtol = 1e-10
  # covariates that are collinear are dropped
  mc = fit(RegressionDiscontinuity, X, RESPONSES["yc"]; covariates = hcat(Z1, Z2, Z1 .+ Z2), bandwidth = 0.4, pilot = 0.6)
  mc2 = fit(RegressionDiscontinuity, X, RESPONSES["yc"]; covariates = hcat(Z1, Z2), bandwidth = 0.4, pilot = 0.6)
  @test mc.ncovariates == 2
  @test mc.estimate ≈ mc2.estimate rtol = 1e-10
  # with clusters the default variance estimator is CR1
  @test fit(RegressionDiscontinuity, X, Y; cluster = G, bandwidth = 0.3).vce == ClusterVariance(1)
end

@testset "interface" begin
  m = fit(RegressionDiscontinuity, X, Y; bandwidth = 0.3, pilot = 0.5)
  @test coef(m) == [m.estimate] && coef(m; method = RobustBiasCorrected()) == [m.estimate_bc]
  @test stderror(m) == [m.se] && stderror(m; method = RobustBiasCorrected()) == [m.se_rbc]
  @test vcov(m) ≈ fill(m.se^2, 1, 1)
  ci = confint(m)
  @test ci ≈ [m.estimate_bc - 1.959963984540054 * m.se_rbc m.estimate_bc + 1.959963984540054 * m.se_rbc]
  @test confint(m; method = Conventional(), level = 0.9)[1] ≈ m.estimate - 1.6448536269514722 * m.se
  t = coeftable(m)
  @test t.method == ["Conventional", "Bias-corrected", "Robust"]
  @test t.se == [m.se, m.se, m.se_rbc] && t.upper[3] ≈ ci[2]
  @test t.z == t.estimate ./ t.se && t.pvalue ≈ 2 .* ccdf.(Normal(), abs.(t.z))
  @test nobs(m) == 600 && bandwidth(m) == (0.3, 0.3)
  @test sprint(show, m) == "RegressionDiscontinuity(sharp, cutoff 0.0, 600 observations)"
  @test occursin("Robust", sprint(show, MIME"text/plain"(), m))
  @test occursin("fuzzy kink", sprint(show, fit(RegressionDiscontinuity, X, RESPONSES["yf"]; treatment = T,
                                                 derivative = 1, degree = 2, bandwidth = 0.6)))
  @inferred fit(RegressionDiscontinuity, X, Y; bandwidth = 0.3)
  @inferred fit(RegressionDiscontinuity, X, Y; bandwidth = 0.3, cluster = G, weights = W)
end

@testset "errors" begin
  @test_throws ArgumentError fit(RegressionDiscontinuity, X, Y)
  @test_throws ArgumentError fit(RegressionDiscontinuity, X, Y; bandwidth = -1)
  @test_throws ArgumentError fit(RegressionDiscontinuity, X, Y; bandwidth = (0.1, 0.2, 0.3))
  @test_throws ArgumentError fit(RegressionDiscontinuity, X, Y; cutoff = 2, bandwidth = 0.3)
  @test_throws ArgumentError fit(RegressionDiscontinuity, X, Y; bandwidth = 0.001)
  @test_throws ArgumentError fit(RegressionDiscontinuity, X, Y; bandwidth = 0.3, vce = ClusterVariance())
  @test_throws DimensionMismatch fit(RegressionDiscontinuity, X, Y; bandwidth = 0.3, treatment = T[1:10])
  @test_throws ArgumentError confint(fit(RegressionDiscontinuity, X, Y; bandwidth = 0.3); method = Honest(1.0))
end

end
